FROM PT_ROLE
ORDER BY CREATE_TIME DESC LIMIT #{limit} OFFSET #{offset}

mapper.insert:
INSERT INTO PT_ROLE (
    ROLE_ID, ROLE_CODE, ROLE_CHNAME, RECORD_STATUS, SYS_CODE,
    CREATE_TIME, CREATE_USER, UPDATE_TIME, UPDATE_USER, REMARK
) VALUES (
    #{roleId}, #{roleCode}, #{roleChName}, #{recordStatus}, #{sysCode},
    #{createTime}, #{createUser}, #{updateTime}, #{updateUser}, #{remark}
