mapper.update:
UPDATE PT_ROLE
ROLE_CODE = #{roleCode}, ROLE_CHNAME = #{roleChName}, RECORD_STATUS = #{recordStatus}, SYS_CODE = #{sysCode}, UPDATE_TIME = #{updateTime}, UPDATE_USER = #{updateUser}, REMARK = #{remark},
